import{_ as n,o as r,c as o,a0 as e}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Artifacts resource","description":"","frontmatter":{},"headers":[],"relativePath":"artifacts/index.md","filePath":"artifacts/index.md"}'),c={name:"artifacts/index.md"};function i(s,t,a,h,l,g){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="artifacts-resource" tabindex="-1">Artifacts resource <a class="header-anchor" href="#artifacts-resource" aria-label="Permalink to &quot;Artifacts resource&quot;">​</a></h1><h2 id="artifact-trong-phat-trien-phan-mem-la-gi" tabindex="-1">Artifact trong phát triển phần mềm là gì? <a class="header-anchor" href="#artifact-trong-phat-trien-phan-mem-la-gi" aria-label="Permalink to &quot;Artifact trong phát triển phần mềm là gì?&quot;">​</a></h2><p><strong>Artifact</strong> (đầu ra / sản phẩm trung gian) là bất kỳ thứ team <strong>tạo ra và lưu lại</strong> để phát triển và vận hành phần mềm, không chỉ <strong>source code</strong> chạy được. Ví dụ thường gặp:</p><ul><li>tài liệu yêu cầu, đặc tả chức năng, thiết kế giao diện hoặc prototype;</li><li>mô tả API, schema, tích hợp;</li><li>kịch bản kiểm thử, testcase, ma trận coverage;</li><li>cấu hình kiến trúc, quyết định kỹ thuật, ghi nhận technical debt;</li><li>script test tự động, contract E2E — vừa là “tài liệu” vừa gắn repo code.</li></ul><p>Code vẫn là artifact quan trọng nhất để <strong>chạy</strong> sản phẩm; các artifact khác giúp team <strong>hiểu đúng</strong>, <strong>kiểm đúng</strong>, và <strong>sửa đúng chỗ</strong> khi thay đổi. Nhiều dự án “chỉ có code” thực ra vẫn có artifact ngầm — ticket, chat, Excel — nhưng không gắn version control và không có chủ sở hữu rõ, nên khó coi là quản lý chuẩn.</p><h2 id="artifacts-resource-la-gi" tabindex="-1">Artifacts resource là gì? <a class="header-anchor" href="#artifacts-resource-la-gi" aria-label="Permalink to &quot;Artifacts resource là gì?&quot;">​</a></h2><p><strong>Artifacts resource</strong> là cách gọi <strong>một nhóm artifact cùng loại</strong> được team (hoặc tổ chức) quy ước đặt ở <strong>một root</strong> — một repo Git, một monorepo package, hoặc một cây thư mục cố định — với <strong>mục đích và quyền sở hữu</strong> thống nhất.</p><ul><li><strong>Resource</strong> nhấn <strong>tài nguyên</strong> (nơi lấy / nơi ghi), không nhầm với một file lẻ.</li><li>Một dự án thường có <strong>nhiều resource</strong>: tài liệu đặc tả, tài liệu test, code FE, code BE, đôi khi tách repo tài liệu và repo test.</li><li><strong>Root</strong> là đường dẫn “bắt đầu từ đây” để tool, CI và agent biết đọc/ghi — không phải mỗi người tự chọn folder.</li></ul><p>FlowGrid map <strong>bốn nhóm resources</strong> chính: docs, tests-docs, code, DSL/platform. Sau <code>flowgrid init</code>, thư mục <strong><code>.flowgrid/</code></strong> (và <code>config.json</code>) ghi <strong>pointer</strong> root từng nhóm và profile adapter — <strong>không</strong> chứa SSOT nghiệp vụ; SSOT nằm trong bốn nhóm dưới.</p><h2 id="team-phan-mem-thuong-quan-ly-artifacts-resource-ra-sao" tabindex="-1">Team phần mềm thường quản lý artifacts resource ra sao? <a class="header-anchor" href="#team-phan-mem-thuong-quan-ly-artifacts-resource-ra-sao" aria-label="Permalink to &quot;Team phần mềm thường quản lý artifacts resource ra sao?&quot;">​</a></h2><ul><li><strong>Phân tách theo vai trò artifact</strong><ul><li>Spec / kiến trúc tách khỏi code production khi có thể — tránh “chỉ đọc được trong code”.</li><li>Thiết kế testcase (document) tách khỏi <strong>chỗ chạy</strong> automation — cùng một ý test có thể được review trước khi gắn Playwright/Cypress.</li></ul></li><li><strong>Gắn version control</strong><ul><li>Artifact quan trọng đi cùng Git (hoặc hệ tương đương) với review merge — không để bản chính trôi trên chat hoặc drive cá nhân.</li></ul></li><li><strong>Owner và reviewer</strong><ul><li>Mỗi resource hoặc nhánh (spec, test plan) có người <strong>chốt</strong>; thay đổi scope có trace (PR, changelog artifact).</li></ul></li><li><strong>Traceability</strong><ul><li>Yêu cầu → spec → testcase → test chạy; API contract → implementation. Mất liên kết thì release và audit khó.</li></ul></li><li><strong>Một nơi chốt (SSOT) cho mỗi chủ đề</strong><ul><li>Tránh hai bản Excel và Confluence cùng mô tả một màn hình; team chọn <strong>một</strong> nguồn để tranh luận và cập nhật (xem <a href="./../overview/">overview § SSOT</a>).</li></ul></li><li><strong>Monorepo vs multi-repo</strong><ul><li><strong>In-repo:</strong> docs và tests-docs có thể nằm <strong>trong repo FE hoặc BE</strong> (<code>docs/</code>, <code>tests/</code>) — resource <strong>khác nhau</strong> về nghĩa; BE thường gom <code>surfaces/integrations/</code> + testcase hook (<code>genType: api-e2e</code>).</li><li><strong>Lớn / nhiều team:</strong> repo Document, repo Test, repo FE/BE — liên kết bằng tag version, submodule, hoặc cấu hình tool trỏ path.</li></ul></li></ul><p>Quy trình agile (sprint, daily) <strong>không thay</strong> việc quản lý resource; nó chỉ nhịp làm việc. Artifact vẫn cần <strong>capture sau khi chốt</strong> và <strong>gate</strong> trước release (review, test, audit) — FlowGrid hỗ trợ phần gate có cấu trúc trên SSOT.</p><h2 id="tam-quan-trong-cua-artifacts-resource" tabindex="-1">Tầm quan trọng của artifacts resource <a class="header-anchor" href="#tam-quan-trong-cua-artifacts-resource" aria-label="Permalink to &quot;Tầm quan trọng của artifacts resource&quot;">​</a></h2><ul><li><strong>Giảm hiểu lệch</strong> giữa BA, dev, QA, vận hành và stakeholder — mọi người tranh luận trên cùng loại file đã chốt.</li><li><strong>Onboarding và handoff</strong> — member mới biết “đọc ở đâu, sửa ở đâu” thay vì hỏi vòng vo.</li><li><strong>Chất lượng release</strong> — testcase document và contract không tách rời code thì regression và lệch FE–BE giảm.</li><li><strong>Tự động hóa và AI</strong> — agent, codegen, audit chỉ tin được khi <strong>path và schema ổn định</strong>; resource là “địa chỉ” cho harness.</li><li><strong>Scale team</strong> — tách repo theo resource khi boundary rõ; không bắt buộc từ ngày đầu nhưng <strong>mô hình tư duy</strong> tách sớm giúp sau này không phải migrate đau.</li></ul><p>Bỏ hoặc làm sơ artifact để “nhanh” vẫn là trade-off; <a href="./../overview/">overview</a> mô tả cách AI + toolkit lấp <strong>công số</strong> duy trì resource mà không bỏ lane.</p><h2 id="flowgrid-bon-nhom-resources-chinh-va-chi-tiet" tabindex="-1">FlowGrid: bốn nhóm resources chính và chi tiết <a class="header-anchor" href="#flowgrid-bon-nhom-resources-chinh-va-chi-tiet" aria-label="Permalink to &quot;FlowGrid: bốn nhóm resources chính và chi tiết&quot;">​</a></h2><ul><li><strong>Docs</strong><ul><li>Bộ artifacts resource về phân tích kỹ thuật, requirement và đặc tả của dự án.</li><li>Tài liệu <strong>SSOT</strong> của dự án; các nhóm resource khác tham chiếu docs để biết <strong>cần làm gì</strong> và <strong>đúng/sai</strong> so với đã chốt.</li><li>Khi phát hiện sai lệch hoặc gap ở công đoạn / artifact khác — cập nhật <strong>docs trước</strong> theo quy trình, rồi lan sang tests-docs, code, DSL.</li><li><strong>Triển khai:</strong> repo Document riêng, hoặc thư mục in-repo (vd. <code>docs/</code>) khi dự án nhỏ.</li><li><strong>FlowGrid:</strong> root ghi trong <code>.flowgrid/config.json</code>; biến môi trường <code>FLOWGRID_DOCS_ROOT</code>; project type <strong>Document</strong> thì cwd thường là docs root.</li><li><strong>Author bundle:</strong> <a href="./docs.html#bundle--authoring-ssot-spec--gen--design">docs.md § Bundle</a> · <a href="https://github.com/ShanYuCoder/flowgrid/blob/main/templates/shared/bundle-authoring.md" target="_blank" rel="noreferrer"><code>bundle-authoring.md</code></a> (toolkit).</li></ul></li><li><strong>Tests-docs</strong><ul><li>Bộ artifacts resource về <strong>tài liệu kiểm thử</strong>: scenario, testcase, suite — không thay chỗ <strong>chạy</strong> automation.</li><li>SSOT cho “cần kiểm gì”; trace về docs để biết kiểm <strong>đúng nghiệp vụ</strong> nào.</li><li>Gap coverage hoặc lệch ma trận → chỉnh tests-docs; nếu sai <strong>yêu cầu</strong> thì quay về docs trước.</li><li><strong>Triển khai:</strong> repo Test riêng, hoặc in-repo (vd. <code>tests/</code>) khi dự án nhỏ.</li><li><strong>FlowGrid:</strong> root trong <code>config.json</code>; <code>FLOWGRID_TESTS_DOC</code> và flag <code>--tests-docs</code> khi audit/engine cần trỏ hub testcase.</li></ul></li><li><strong>Code</strong><ul><li>Bộ artifacts resource <strong>mã chạy được</strong>: FE, BE, fullstack.</li><li>Implementation và contract runtime; đối chiếu docs (spec/API) và tests-docs (kỳ vọng kiểm thử).</li><li>Lệch hành vi hoặc API → xác định sửa code hay cập nhật docs/tests-docs; <strong>đổi nghiệp vụ</strong> thì docs (và testcase liên quan) đi trước code.</li><li><strong>e2e-root:</strong> repo/thư mục (thường FE) nơi chạy và lưu spec automation; <strong>khác</strong> root tests-docs (document vs chạy).</li><li><strong>FlowGrid:</strong> project type FE/BE/Fullstack; pointer docs/tests trong config; <code>--e2e-root</code> cho audit E2E và codegen testcase; harness skills/MCP sync vào repo làm việc (thường cùng repo code).</li><li><strong>Contract triển khai:</strong> <a href="./code.html#contract-field-registry">field registry &amp; <code>contract:gen</code></a> · <a href="./code.html#portal-api">Portal ↔ API (envelope, list, wire)</a> — chi tiết trên <a href="./code.html">code.md</a>.</li><li><strong>E2E (e2e-root):</strong> <a href="./code.html#e2e-testids">Playwright &amp; testId</a> · <a href="./code.html#e2e-semantic-assertions">semantic UI / axe</a> — plan testcase trên <a href="./tests-docs.html">tests-docs</a>.</li><li><strong>Portal FE (adapter):</strong> <a href="./code.html#portal-fe-layers">bốn tầng composable → service → store → model</a> · <a href="./code.html#page-lifecycle">page lifecycle registry</a>.</li></ul></li><li><strong>DSL &amp; platform</strong><ul><li>Quy ước chung: DNA kiến trúc, markers/tags trên bundle, registry design/unit, lexicon <strong>ArtifactGraph</strong> — không thay spec nghiệp vụ trong docs.</li><li>Giúp toolkit và agent đọc/ghi <strong>đúng format</strong> trên các nhóm resource kia.</li><li>Đổi quy ước platform → cập nhật DSL theo policy team; không dùng DSL để “vá” spec sai trong docs.</li><li><strong>FlowGrid:</strong> adapter profile (stack FE/BE) trong <code>.flowgrid/config.json</code>; <code>.artifactgraph/</code> khi bật; <code>registries/</code>, markers — thường cùng repo docs hoặc code, không có env root riêng như docs/tests-docs.</li><li><strong>Skills agent vs docs web:</strong> harness <code>SKILL.md</code> (sau sync) là policy chạy; <a href="./../references/skills/spec.html">references/skills/</a> + <a href="./../references/cli-and-commands.html#skills-harness-vs-docs">CLI § harness vs web</a>.</li></ul></li></ul>',17)])])}const m=n(c,[["render",i]]);export{u as __pageData,m as default};
